    {
      "id": 2,
      "claim": "The friend intentionally jumped out, brandished a toy pistol, and seized the necklace, causing the woman to become hysterical and plead for her life.",
      "evidence": "Fact pattern describing the friend’s conduct and the woman’s reaction.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "A reasonable person in the woman’s position would apprehend imminent bodily harm from the toy pistol and the sudden grab.",
      "evidence": "Objective standard for apprehension in assault; the woman’s hysteria shows she perceived the threat as imminent.",
      "weight": 0.15,
      "depends_on": [1,2]
    },
    {
      "id": 4,
      "claim": "All elements of assault are satisfied; therefore the friend is guilty of assault.",
      "evidence": "Steps 1‑3 establish intent, act, and reasonable apprehension.",
      "weight": 0.15,
      "depends_on": [1,2,3]
    },
    {
      "id": 5,
      "claim": "Robbery requires (a) taking personal property from the person or presence of another, (b) by force or intimidation, and (c) with intent to permanently deprive the owner.",
      "evidence": "Standard common‑law definition of robbery.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 6,
      "claim": "The friend lacked intent to permanently deprive because she immediately returned the necklace and explained the act was a joke.",
      "evidence": "Fact pattern: friend handed the necklace back and stated the purpose was to frighten.",
      "weight": 0.07,
      "depends_on": [5]
    },
    {
      "id": 7,
      "claim": "Battery requires intentional harmful or offensive contact with the plaintiff’s person; while the friend touched the woman’s neck, the contact was incidental to the threat and not the primary culpable act.",
      "evidence": "Legal distinction that the gravamen of the conduct is the threatening use of a weapon, which is captured by assault; battery is not the best charge in this context.",
      "weight": 0.08,
